            15 -> anchor_setting_info = MultiLiveAnchorPanelSettings.ADAPTER.decode(reader)
            16 -> action_id = ProtoAdapter.INT64.decode(reader)
            17 -> linked_users.add(LinkmicUserInfo.ADAPTER.decode(reader))
            18 -> source_type = ProtoAdapter.INT64.decode(reader)
            else -> reader.readUnknownField(tag)
          }
        }
        return LinkerReplyContent(
          from_user_id = from_user_id,
          from_room_id = from_room_id,
          from_user_linkmic_info = from_user_linkmic_info,
          to_user_id = to_user_id,
          to_user_linkmic_info = to_user_linkmic_info,
          link_type = link_type,
          reply_status = reply_status,
          linker_setting = linker_setting,
          from_user = from_user,
          to_user = to_user,
          rtc_ext_info_map = rtc_ext_info_map,
          invitee_mic_idx_update_info = invitee_mic_idx_update_info,
          applier_mic_idx_info_map = applier_mic_idx_info_map,
          anchor_multi_live_enum = anchor_multi_live_enum,
          anchor_setting_info = anchor_setting_info,
          action_id = action_id,
          linked_users = linked_users,
          source_type = source_type,
          unknownFields = unknownFields
        )
      }

      override fun redact(`value`: LinkerReplyContent): LinkerReplyContent = value.copy(
        from_user_linkmic_info = value.from_user_linkmic_info?.let(LinkmicInfo.ADAPTER::redact),
        to_user_linkmic_info = value.to_user_linkmic_info?.let(LinkmicInfo.ADAPTER::redact),
        linker_setting = value.linker_setting?.let(LinkerSetting.ADAPTER::redact),
        from_user = value.from_user?.let(User.ADAPTER::redact),
        to_user = value.to_user?.let(User.ADAPTER::redact),
        invitee_mic_idx_update_info = value.invitee_mic_idx_update_info?.let(LinkerMicIdxUpdateInfo.ADAPTER::redact),
        anchor_setting_info = value.anchor_setting_info?.let(MultiLiveAnchorPanelSettings.ADAPTER::redact),
        linked_users = value.linked_users.redactElements(LinkmicUserInfo.ADAPTER),
        unknownFields = ByteString.EMPTY
      )
    }

    private const val serialVersionUID: Long = 0L
  }
